-- NaCCA curriculum for Basic 8 (part 1 of 2): 231 indicators (Career Technology, Creative Arts, English Language, Ghanaian Language, Mathematics, Religious & Moral Education).
-- Needs 20261029_curriculum_subject_key.sql first. Safe to run again: it replaces these subjects for Basic 8.
delete from public.curriculum_items
 where lower(class_name) = 'basic 8' and subject_key in ('career technology', 'creative arts', 'english', 'ghanaian language', 'maths', 'rme');

